  "#0096c7","#00b4d8","#48cae4","#90e0ef","#caf0f8",
];

const ThumbnailGrid: React.FC<{ progress: number; count: number }> = ({
  progress,
  count,
}) => {
  const cols = 12;
  const rows = 8;
  const thumbW = 3840 / cols;
  const thumbH = 2160 / rows;

  return (
    <AbsoluteFill>
      {Array.from({ length: rows }).map((_, row) =>
        Array.from({ length: cols }).map((_, col) => {
          const idx = row * cols + col;
          const delay = idx * 0.3;
          const localProgress = Math.max(
            0,
            Math.min(1, (progress * count - delay) / 3)
          );
          const color = THUMB_COLORS[idx % THUMB_COLORS.length];
          const opacity = localProgress * 0.85;
          const scale = 0.5 + localProgress * 0.5;

          return (
            <div
              key={`${row}-${col}`}
              style={{
                position: "absolute",
                left: col * thumbW,
                top: row * thumbH,
                width: thumbW - 4,
                height: thumbH - 4,
                margin: 2,
                backgroundColor: color,
                borderRadius: 8,
                opacity,
                transform: `scale(${scale})`,
                transformOrigin: "center",
                overflow: "hidden",
                display: "flex",
                flexDirection: "column",
              }}
            >
              {/* thumbnail stripe */}
              <div
                style={{
                  height: "65%",
                  backgroundColor: color,
                  backgroundImage: `linear-gradient(135deg, ${color}cc, ${color}44)`,
                }}
              />
              <div
                style={{
                  height: "35%",
                  backgroundColor: "rgba(0,0,0,0.6)",
                  padding: "6px 10px",
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
