// ─────────────────────────────────────────────
// Duration calculations
// ─────────────────────────────────────────────
const S1 = 93;
const S2 = 75;
const S3 = 97;
const S4 = 163;
const S5 = 168;
const S6 = 126;
const S7 = 203;
const BOOKEND_OPEN = 20;
const BOOKEND_CLOSE = 25;

// Total = sum of all + bookends, minus transition overlaps
// Transitions: open→S1, S1→S2, S2→S3, S3→S4, S4→S5, S5→S6, S6→S7, S7→close = 8 transitions
export const durationInFrames =
  BOOKEND_OPEN +
  S1 +
  S2 +
  S3 +
  S4 +
  S5 +
  S6 +
  S7 +
  BOOKEND_CLOSE -
  8 * TRANSITION;

// ─────────────────────────────────────────────
// Main Composition
// ─────────────────────────────────────────────
const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      {/* Opening black */}
      <TransitionSeries.Sequence durationInFrames={BOOKEND_OPEN}>
